// @domain: awareness
//! #4716 — `store.kind = door`: a generated API writes through the door, never to the
//! store with the store's password. The door takes the same change as batch lines;
//! these tests prove the lines change a row exactly as the SPARQL path does, and that
//! a door store with no token writes nothing. Generated by athena-gen — DO NOT EDIT.

use crate::model::NS;
use crate::rules::Cell;
use crate::store::{write_lines, write_update, Door, Embedded, Engine, Remote, RowStore, Sparql};

const G: &str = "urn:test:door";

/// What the door does with batch lines, on an embedded store, for the comparison.
fn run_lines(e: &Embedded, lines: &[String]) {
    for l in lines {
        let f: Vec<&str> = l.split('\t').collect();
        let q = match f[0] {
            "DEL" => format!("DELETE WHERE {{ GRAPH <{G}> {{ {} {} ?o }} }}", f[1], f[2]),
            _ => format!("INSERT DATA {{ GRAPH <{G}> {{ {} {} {} }} }}", f[1], f[2], f[3]),
        };
        e.update(&q).unwrap();
    }
}

fn predicates(e: &Embedded, s: &str) -> Vec<String> {
    e.select(&format!("SELECT DISTINCT ?p WHERE {{ GRAPH <{G}> {{ <{s}> ?p ?o }} }}"))
        .unwrap()
        .iter()
        .filter_map(|r| r.get("p").and_then(|v| v["value"].as_str()).map(String::from))
        .collect()
}

fn lit(v: &str) -> Vec<Cell> {
    vec![Cell::Literal(v.into(), "string")]
}

#[test]
fn door_lines_change_a_row_exactly_as_the_sparql_path_does() {
    let s = format!("{NS}thing-a");
    let steps: Vec<(Option<&str>, Vec<(String, Vec<Cell>)>, bool)> = vec![
        (Some("Thing"), vec![("label".into(), lit("a")), ("status".into(), lit("new"))], false),
        (None, vec![("status".into(), lit("open"))], false),
        (Some("Thing"), vec![("label".into(), lit("b"))], true),
    ];
    let (via_sparql, via_door) = (Embedded::memory(), Embedded::memory());
    for (t, fields, whole) in &steps {
        via_sparql.update(&write_update(G, &s, *t, fields, *whole)).unwrap();
        let existing = if *whole { predicates(&via_door, &s) } else { Vec::new() };
        run_lines(&via_door, &write_lines(&s, *t, fields, *whole, &existing));
    }
    assert_eq!(via_sparql.dump_trig().unwrap(), via_door.dump_trig().unwrap());
}

fn door(token: &str) -> Sparql {
    Sparql::over(Box::new(Door {
        reads: Remote { endpoint: "http://127.0.0.1:1".into(), auth: None },
        door: "http://127.0.0.1:1".into(),
        token: token.into(),
    }))
}

// negative proof: with no token, a door store must refuse before it sends anything.
#[test]
fn negative_proof_a_door_store_without_a_token_writes_nothing() {
    let e = door("").write(G, &format!("{NS}thing-a"), None, &[("status".into(), lit("x"))], false).unwrap_err();
    assert!(e.contains("no service token"), "{e}");
}

// negative proof: a door store never sends a raw SPARQL update, whatever asks.
#[test]
fn negative_proof_a_door_store_sends_no_sparql_update() {
    let e = door("tok").engine().update("INSERT DATA { <a> <b> <c> }").unwrap_err();
    assert!(e.contains("writes go through the door"), "{e}");
}
